CREATE TABLE `velix_collage_jobs` (`id` text PRIMARY KEY NOT NULL, `project_id` text NOT NULL REFERENCES `video_projects`(`id`) ON DELETE CASCADE, `prompt` text NOT NULL, `aspect_ratio` text NOT NULL, `duration_seconds` real NOT NULL, `status` text NOT NULL, `metaphor` text, `still_path` text, `clip_path` text, `rights_reference_id` text, `estimated_cost_usd` real NOT NULL, `error` text, `created_at` text NOT NULL DEFAULT (datetime('now')), `updated_at` text NOT NULL DEFAULT (datetime('now')))
